<?php
declare(strict_types=1);
session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=$_SESSION['role'];$uid=(int)$_SESSION['user_id'];$canAssign=in_array($role,['director','sub_director','headteacher','head_academic','assistant_academic'],true);$canRegister=in_array($role,['director','sub_director','headteacher','head_academic','assistant_academic','admin'],true);$canResult=in_array($role,['teacher','head_academic','assistant_academic','examination_officer','headteacher'],true);$error='';$saved=isset($_GET['saved']);
$pdo=null;$schools=[];try{$pdo=db();if(in_array($role,['system_admin','sub_admin'],true))$schools=$pdo->query('SELECT id,name FROM schools ORDER BY name')->fetchAll();else{$q=$pdo->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();}}catch(Throwable $ex){$error='Academic data is unavailable. Apply the latest database schema.';}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$schoolId=(int)($_POST['school_id']??0);if(!array_filter($schools,fn($s)=>(int)$s['id']===$schoolId)){$error='Choose a school within your access.';}else{try{if($action==='assignment'&&$canAssign){$teacher=(int)($_POST['teacher_id']??0);$class=trim((string)($_POST['class_level']??''));$subject=trim((string)($_POST['subject']??''));$q=$pdo->prepare("SELECT id FROM users u JOIN school_memberships m ON m.user_id=u.id WHERE u.id=? AND u.role='teacher' AND m.school_id=? AND u.status='active'");$q->execute([$teacher,$schoolId]);if(!$q->fetch()||$class===''||$subject==='')throw new DomainException('Choose an active teacher in the selected school and enter class and subject.');$q=$pdo->prepare('INSERT INTO teacher_assignments(user_id,school_id,class_level,subject) VALUES(?,?,?,?)');$q->execute([$teacher,$schoolId,$class,$subject]);$entity='teacher_assignment';$id=(int)$pdo->lastInsertId();}
elseif($action==='pupil'&&$canRegister){$admission=trim((string)($_POST['admission_number']??''));$first=trim((string)($_POST['first_name']??''));$last=trim((string)($_POST['last_name']??''));$class=trim((string)($_POST['class_level']??''));$stream=trim((string)($_POST['stream']??''));$scholar=$_POST['scholar_type']??'day';if(!$admission||!$first||!$last||!$class||!in_array($scholar,['day','boarding'],true))throw new DomainException('Complete admission number, pupil name, class and scholar type.');$q=$pdo->prepare('INSERT INTO pupils(school_id,admission_number,first_name,last_name,date_of_birth,class_level,stream,scholar_type,guardian_name,guardian_phone) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$schoolId,$admission,$first,$last,$_POST['date_of_birth']?:null,$class,$stream?:null,$scholar,trim((string)($_POST['guardian_name']??''))?:null,trim((string)($_POST['guardian_phone']??''))?:null]);$entity='pupil';$id=(int)$pdo->lastInsertId();}
elseif($action==='result'&&$canResult){$pupil=(int)($_POST['pupil_id']??0);$subject=trim((string)($_POST['subject']??''));$assessment=trim((string)($_POST['assessment']??''));$score=filter_var($_POST['score']??null,FILTER_VALIDATE_FLOAT);$max=filter_var($_POST['max_score']??null,FILTER_VALIDATE_FLOAT);$q=$pdo->prepare('SELECT * FROM pupils WHERE id=? AND school_id=? AND status=\'active\'');$q->execute([$pupil,$schoolId]);$student=$q->fetch();$permitted=in_array($role,['head_academic','assistant_academic','examination_officer','headteacher'],true);if($role==='teacher'){$a=$pdo->prepare('SELECT id FROM teacher_assignments WHERE user_id=? AND school_id=? AND class_level=? AND subject=? AND active=1');$a->execute([$uid,$schoolId,$student['class_level']??'',$subject]);$permitted=(bool)$a->fetch();}$d=$pdo->prepare('SELECT id FROM result_delegations WHERE user_id=? AND school_id=? AND active=1 AND academic_year=? AND (class_level IS NULL OR class_level=?)');$d->execute([$uid,$schoolId,(int)date('Y'),$student['class_level']??'']);$permitted=$permitted||(bool)$d->fetch();if(!$student||!$permitted||!$subject||!$assessment||$score===false||$max===false||$max<=0||$score<0||$score>$max)throw new DomainException('Check the pupil, assignment or delegation, and score range.');$q=$pdo->prepare('INSERT INTO pupil_results(pupil_id,school_id,class_level,stream,subject,assessment,academic_year,score,max_score,entered_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$pupil,$schoolId,$student['class_level'],$student['stream'],$subject,$assessment,(int)date('Y'),$score,$max,$uid]);$entity='pupil_result';$id=(int)$pdo->lastInsertId();}
else{http_response_code(403);exit('This action is not available to your role.');}$a=$pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id) VALUES(?,?,?,?)');$a->execute([$uid,'create',$entity,$id]);header('Location: academics.php?saved=1');exit;}catch(DomainException $ex){$error=$ex->getMessage();}catch(Throwable $ex){$error='The record could not be saved. Check required fields, duplicate records and database setup.';}}}
$teachers=[];$pupils=[];$results=[];$assignments=[];try{if($schools){$ids=array_column($schools,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT u.id,u.name,m.school_id FROM users u JOIN school_memberships m ON m.user_id=u.id WHERE u.role='teacher' AND u.status='active' AND m.school_id IN ($marks) ORDER BY u.name");$q->execute($ids);$teachers=$q->fetchAll();$q=$pdo->prepare("SELECT p.*,s.name school_name FROM pupils p JOIN schools s ON s.id=p.school_id WHERE p.school_id IN ($marks) AND p.status='active' ORDER BY p.last_name,p.first_name LIMIT 400");$q->execute($ids);$pupils=$q->fetchAll();$q=$pdo->prepare("SELECT r.*,p.first_name,p.last_name,u.name entered_by_name FROM pupil_results r JOIN pupils p ON p.id=r.pupil_id JOIN users u ON u.id=r.entered_by WHERE r.school_id IN ($marks) ORDER BY r.updated_at DESC LIMIT 200");$q->execute($ids);$results=$q->fetchAll();$q=$pdo->prepare("SELECT a.*,u.name teacher_name,s.name school_name FROM teacher_assignments a JOIN users u ON u.id=a.user_id JOIN schools s ON s.id=a.school_id WHERE a.school_id IN ($marks) AND a.active=1 ORDER BY s.name,a.class_level,a.subject");$q->execute($ids);$assignments=$q->fetchAll();}}catch(Throwable $ex){}
