<?php if($canAssign):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">TEACHING</div><h2>Assign a teacher</h2></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="assignment"><div class="form-grid"><div><label for="assign-school">School</label><select name="school_id" id="assign-school" required><option value="">Choose school</option><?php foreach($schools as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div><label for="teacher">Teacher</label><select name="teacher_id" id="teacher" required><option value="">Choose teacher</option><?php foreach($teachers as $t):?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach;?></select></div><div><label for="assign-class">Class level</label><input name="class_level" id="assign-class" required maxlength="80"></div><div><label for="subject">Subject</label><input name="subject" id="subject" required maxlength="100"></div></div><button class="button primary" type="submit">Save assignment</button></form></section><?php endif;?>
<?php if($canResult):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">ASSESSMENT</div><h2>Enter a result</h2></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="result"><div class="form-grid"><div><label for="result-school">School</label><select name="school_id" id="result-school" required><option value="">Choose school</option><?php foreach($schools as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div><label for="pupil">Pupil</label><select name="pupil_id" id="pupil" required><option value="">Choose pupil</option><?php foreach($pupils as $p):?><option value="<?=$p['id']?>"><?=e($p['first_name'].' '.$p['last_name'].' · '.$p['class_level'].' · '.$p['school_name'])?></option><?php endforeach;?></select></div><div><label for="result-subject">Subject</label><input name="subject" id="result-subject" required maxlength="100"></div><div><label for="assessment">Assessment</label><input name="assessment" id="assessment" required maxlength="120"></div><div><label for="score">Score</label><input name="score" id="score" type="number" min="0" step="0.01" required></div><div><label for="max-score">Maximum score</label><input name="max_score" id="max-score" type="number" min="0.01" step="0.01" required></div></div><button class="button primary" type="submit">Save result</button></form></section><?php endif;?>
<section class="content-section"><div class="section-heading"><div><div class="eyebrow">CLASSROOM</div><h2>Teaching assignments</h2></div></div><?php if(!$assignments):?><div class="empty-state"><h3>No assignments found</h3><p>Teacher assignments appear here when a school leader links a teacher to a subject and class.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Teacher</th><th>School</th><th>Class</th><th>Subject</th></tr></thead><tbody><?php foreach($assignments as $a):?><tr><td><?=e($a['teacher_name'])?></td><td><?=e($a['school_name'])?></td><td><?=e($a['class_level'])?></td><td><?=e($a['subject'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">PUPIL DIRECTORY</div><h2>Pupils</h2></div><span class="count-pill"><?=count($pupils)?> pupils</span></div><?php if($pupils):?><div class="table-wrap"><table><thead><tr><th>Admission</th><th>Pupil</th><th>School / class</th><th>Scholar type</th></tr></thead><tbody><?php foreach($pupils as $p):?><tr><td><?=e($p['admission_number'])?></td><td><?=e($p['first_name'].' '.$p['last_name'])?></td><td><?=e($p['school_name'].' · '.$p['class_level'].($p['stream']?' / '.$p['stream']:''))?></td><td><?=e(ucfirst($p['scholar_type']))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No pupils registered</h3><p>Register a pupil to begin building the school directory.</p></div><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ASSESSMENT RECORDS</div><h2>Recent results</h2></div></div><?php if($results):?><div class="table-wrap"><table><thead><tr><th>Pupil</th><th>Class</th><th>Subject</th><th>Assessment</th><th>Score</th><th>Year</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['class_level'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['assessment'])?></td><td><?=e($r['score'].' / '.$r['max_score'])?></td><td><?=e((string)$r['academic_year'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No results yet</h3><p>Saved assessment results will appear here.</p></div><?php endif;?></section></div></main></div></body></html>
